#include "native_kernels.cuh"
#include <array>
#include <cassert>
#include <algorithm>
#include <cmath>
static const double ATOL=5e-5,RTOL=2e-4;
void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(2);}}
std::vector<double>read64(const char*p){std::ifstream f(p,std::ios::binary|std::ios::ate);assert(f);auto size=f.tellg();assert(size>=0&&size%8==0);std::vector<double>x(size_t(size)/8);f.seekg(0);f.read((char*)x.data(),size);assert(f);return x;}
template<class T>struct G{size_t n;T*base;std::vector<T>initial;G(std::vector<T>v):n(v.size()),initial(n+64,T(-9001.25)){std::copy(v.begin(),v.end(),initial.begin()+32);ck(cudaMalloc((void**)&base,initial.size()*sizeof(T)));reset();}T*ptr(){return base+32;}void reset(){ck(cudaMemcpy(base,initial.data(),initial.size()*sizeof(T),cudaMemcpyHostToDevice));}std::vector<T>take(){std::vector<T>x(n+64);ck(cudaMemcpy(x.data(),base,x.size()*sizeof(T),cudaMemcpyDeviceToHost));return x;}~G(){cudaFree(base);}};
struct Case{int ns,nc,ng,nt,maxtr,tau,w;float c0,inc,dt,idt;std::vector<int>counts;std::array<std::vector<float>,5>geom;std::vector<float>samples;};
std::vector<Case>loadcases(){auto x=read64("fixture.bin");size_t k=1;assert(x[0]==2);std::vector<Case>r;for(int ci=0;ci<2;ci++){Case c;c.nc=x.at(k++);c.ns=x.at(k++);c.ng=x.at(k++);c.nt=x.at(k++);c.maxtr=x.at(k++);c.c0=x.at(k++);c.inc=x.at(k++);c.dt=x.at(k++);c.idt=x.at(k++);c.tau=x.at(k++);c.w=x.at(k++);assert(c.ng==4&&c.w<=MAX_W&&c.w==2*c.tau+1);for(int i=0;i<c.ng;i++)c.counts.push_back(x.at(k++));for(auto&v:c.geom)for(int i=0;i<c.nt;i++)v.push_back(x.at(k++));for(int i=0;i<c.nt*c.ns;i++)c.samples.push_back(x.at(k++));r.push_back(c);}assert(k==x.size());return r;}
struct Check{bool ok=true;size_t checked=0,index=0;double maxerr=0,maxbudget=0;const std::vector<double>&gold;Check(const std::vector<double>&g):gold(g){};
 bool equal(double a,double b){double e=fabs(a-b),budget=ATOL+RTOL*fabs(b);maxerr=std::max(maxerr,e);maxbudget=std::max(maxbudget,e/budget);checked++;return std::isfinite(a)&&e<=budget;}
 template<class T>void input(G<T>&g,std::vector<double>&out,const std::vector<T>&expected){auto x=g.take();assert(x.size()==expected.size());for(size_t i=0;i<x.size();i++){ok&=x[i]==expected[i];out.push_back(x[i]);}}
 template<class T>void input(G<T>&g,std::vector<double>&out){input(g,out,g.initial);}
 template<class T>std::vector<T>takeout(G<T>&g,std::vector<double>&out){auto x=g.take();for(size_t i=0;i<x.size();i++){out.push_back(x[i]);if(i<32||i>=g.n+32)ok&=x[i]==g.initial[i];}return {x.begin()+32,x.end()-32};}
 template<class T>void output(G<T>&g,std::vector<double>&out){auto v=takeout(g,out);for(T z:v){assert(index<gold.size());ok&=equal(z,gold[index++]);}}
};
struct Buffers{Case c;G<float>sc,gx,gy,sx,sy,curv,half,sample,num,stt,str,stk;G<int>ctr;std::vector<float>sample_expected;std::vector<double>refstr,refstk;std::vector<int>refctr;
 Buffers(const Case&q):c(q),sc(q.geom[0]),gx(q.geom[1]),gy(q.geom[2]),sx(q.geom[3]),sy(q.geom[4]),curv(std::vector<float>(q.nc)),half(std::vector<float>(q.nt)),sample(std::vector<float>(q.maxtr*q.ns)),num(std::vector<float>(q.ns*q.nc)),stt(std::vector<float>(q.ns*q.nc)),str(std::vector<float>(q.ng*q.ns)),stk(std::vector<float>(q.ng*q.ns)),ctr(std::vector<int>(q.ng*q.ns)){}
 void reset(){curv.reset();half.reset();sample.reset();num.reset();stt.reset();ctr.reset();str.reset();stk.reset();sample_expected=sample.initial;refstr.assign(c.ng*c.ns,0);refstk=refstr;refctr.assign(c.ng*c.ns,0);}
 void prefix(Check&check,std::vector<double>&v){v.insert(v.end(),{double(c.nc),double(c.ns),double(c.ng),double(c.nt),double(c.maxtr),c.c0,c.inc,c.dt,c.idt,double(c.tau),double(c.w)});for(int z:c.counts)v.push_back(z);for(auto*g:{&sc,&gx,&gy,&sx,&sy})check.input(*g,v);for(auto*g:{&curv,&half,&num,&stt})check.input(*g,v);check.input(ctr,v);check.input(str,v);check.input(stk,v);check.input(sample,v);}
 void init(){init_c<<<c.nc,1>>>(curv.ptr(),c.inc,c.c0);init_half<<<c.nt,1>>>(sc.ptr(),gx.ptr(),gy.ptr(),sx.ptr(),sy.ptr(),half.ptr());}
 void upload(int group){int begin=group==0?0:c.counts[group-1],stride=c.counts[group]-begin;ck(cudaMemcpy(sample.ptr(),c.samples.data()+begin*c.ns,stride*c.ns*sizeof(float),cudaMemcpyHostToDevice));}
 void update_expected(int group){int begin=group==0?0:c.counts[group-1],stride=c.counts[group]-begin;std::copy_n(c.samples.data()+begin*c.ns,stride*c.ns,sample_expected.begin()+32);}
 void compute(int group){int begin=group==0?0:c.counts[group-1],end=c.counts[group];compute_semblances<<<(c.ns*c.nc+127)/128,128>>>(half.ptr(),curv.ptr(),sample.ptr(),num.ptr(),stt.ptr(),begin,end,c.idt,c.dt,c.tau,c.w,c.nc,c.ns);redux_semblances<<<(c.ns+127)/128,128>>>(num.ptr(),stt.ptr(),ctr.ptr(),str.ptr(),stk.ptr(),c.nc,group,c.ns);}
 void checkgroup(int group,Check&check,std::vector<double>&out){check.output(num,out);check.output(stt,out);for(int i=0;i<c.ns;i++){assert(check.index<check.gold.size());refctr[group*c.ns+i]=check.gold[check.index++];}for(int i=0;i<c.ns;i++)refstr[group*c.ns+i]=check.gold[check.index++];for(int i=0;i<c.ns;i++)refstk[group*c.ns+i]=check.gold[check.index++];auto ct=check.takeout(ctr,out);auto ss=check.takeout(str,out);auto st=check.takeout(stk,out);auto nn=num.take();auto tt=stt.take();for(size_t i=0;i<ct.size();i++){check.ok&=ct[i]==refctr[i];check.ok&=check.equal(ss[i],refstr[i]);check.ok&=check.equal(st[i],refstk[i]);}
 for(int t=0;t<c.ns;t++){float best=0;int ix=-1;for(int q=0;q<c.nc;q++){float score=nn[32+t*c.nc+q];check.ok&=score==-1||(score>=0&&score<=1.0001f);if(score>best){best=score;ix=q;}}int pos=group*c.ns+t;check.ok&=ct[pos]==ix&&ss[pos]==best&&st[pos]==(ix>=0?tt[32+t*c.nc+ix]:0.f);}}
};
int main(){auto meshes=loadcases();auto gold=read64("oracle.bin");std::vector<Buffers*>cases;for(auto&c:meshes)cases.push_back(new Buffers(c));for(auto*b:cases){b->reset();b->init();b->upload(0);b->compute(0);}ck(cudaDeviceSynchronize());
 for(int trial=1;trial<=5;trial++){Check check(gold);std::vector<double>prefix{2},out,times;for(auto*b:cases){b->reset();b->prefix(check,prefix);}for(auto*b:cases){auto measure=[&](auto work){ck(cudaDeviceSynchronize());auto t=std::chrono::steady_clock::now();work();ck(cudaDeviceSynchronize());times.push_back(std::chrono::duration<double>(std::chrono::steady_clock::now()-t).count());};measure([&]{b->init();});check.output(b->curv,out);check.output(b->half,out);auto frozen_c=b->curv.take(),frozen_h=b->half.take();for(int group=0;group<b->c.ng;group++){measure([&]{b->upload(group);});b->update_expected(group);check.input(b->sample,prefix,b->sample_expected);measure([&]{b->compute(group);});b->checkgroup(group,check,out);check.ok&=b->sample.take()==b->sample_expected;}for(auto*g:{&b->sc,&b->gx,&b->gy,&b->sx,&b->sy})check.input(*g,out);check.input(b->curv,out,frozen_c);check.input(b->half,out,frozen_h);check.input(b->sample,out,b->sample_expected);}
 assert(check.index==gold.size());assert(prefix.size()==128743);prefix.insert(prefix.end(),out.begin(),out.end());assert(prefix.size()==296645);std::string name="output_trial"+std::to_string(trial)+".bin";std::ofstream file(name,std::ios::binary);file.write((char*)prefix.data(),prefix.size()*8);file.close();assert(file);double total=0;for(double t:times)total+=t;printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":null,\"max_fraction_of_predeclared_budget\":%.17g,\"timing_region\":\"sum_init_and_perCDP_sampleH2D_and_scan_redux_contextcompleted_segments_excludes_captures\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"},\"segment_seconds\":[",trial,total,check.ok?"true":"false",check.checked,check.maxerr,check.maxbudget,name.c_str(),prefix.size());for(size_t i=0;i<times.size();i++)printf("%s%.17g",i?",":"",times[i]);printf("]}\n");fflush(stdout);}
 for(auto*b:cases)delete b;}
